/* ------------------------------------------------------------------
 * universe.js — the full Indian equity universe: every NSE-listed
 * equity plus every BSE-listed scrip that is not also on NSE.
 *
 * Sources (all free, no API key):
 *   data/nse-symbols.json   generated by node tools/build-universe.mjs
 *   data/bse-symbols.json   BSE-only scrips (deduped by ISIN)
 *   data/baskets.json       Nifty 50 / Next 50 / Midcap 150 / Smallcap 250 / 500
 *   NSE archives            re-fetched automatically once a day through
 *                           CONFIG.proxies so the list stays current
 *                           (see refreshIfStale()).
 *   BSE daily bhavcopy      refreshed on demand (see refreshBse()).
 *
 * `count()` is the NSE listing count; `bseCount()` and `totalCount()`
 * cover the merged universe the UI searches and displays.
 * ------------------------------------------------------------------ */

const Universe = (() => {
  const CACHE_KEY = 'smd.universe';
  const REFRESH_KEY = 'smd.universe.refreshedAt';
  const CACHE_MAX_AGE = 30 * 24 * 60 * 60 * 1000; // reuse the cached list for 30 days
  const REFRESH_EVERY = 24 * 60 * 60 * 1000;      // try to update the list daily

  const EQUITY_URL = 'https://nsearchives.nseindia.com/content/equities/EQUITY_L.csv';
  const BASKET_FILES = [
    'nifty50', 'niftynext50', 'niftymidcap150', 'niftysmallcap250', 'nifty500'
  ];
  /** BSE daily bhavcopy — the BSE equity master. */
  const BSE_URL = (date) => {
    const y = date.getUTCFullYear();
    const m = String(date.getUTCMonth() + 1).padStart(2, '0');
    const d = String(date.getUTCDate()).padStart(2, '0');
    return `https://www.bseindia.com/download/BhavCopy/Equity/BhavCopy_BSE_CM_0_0_0_${y}${m}${d}_F_0000.CSV`;
  };

  /** NSE industry -> sector key used by the locale files. */
  const INDUSTRY_KEYS = {
    'Financial Services': 'financial',
    'Capital Goods': 'capitalgoods',
    Healthcare: 'healthcare',
    'Automobile and Auto Components': 'auto',
    'Fast Moving Consumer Goods': 'fmcg',
    Chemicals: 'chemicals',
    'Information Technology': 'it',
    'Consumer Services': 'consumerservices',
    'Metals & Mining': 'metals',
    Power: 'power',
    'Oil Gas & Consumable Fuels': 'oilgas',
    'Consumer Durables': 'durables',
    Services: 'services',
    Realty: 'realty',
    Construction: 'construction',
    'Construction Materials': 'constructionmaterials',
    Telecommunication: 'telecom',
    Textiles: 'textiles',
    'Media Entertainment & Publication': 'media',
    Diversified: 'diversified'
  };

  const state = {
    items: [],
    index: new Map(),
    bseItems: [],
    bseIndex: new Map(),
    baskets: {},
    updatedAt: 0,
    bseUpdatedAt: 0,
    refreshedAt: 0,
    ready: false,
    loading: null,
    localised: new Map()
  };

  /* ------------------------------ storage -------------------------- */

  function read(key) {
    try {
      const raw = localStorage.getItem(key);
      return raw ? JSON.parse(raw) : null;
    } catch (err) { return null; }
  }

  function write(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); } catch (err) { /* quota */ }
  }

  /* ------------------------------- parsing ------------------------- */

  /** Minimal CSV parser that tolerates quoted fields. */
  function parseCsv(text) {
    const rows = [];
    let row = [];
    let field = '';
    let quoted = false;
    const input = String(text).replace(/^\uFEFF/, '');

    for (let i = 0; i < input.length; i += 1) {
      const char = input[i];
      if (quoted) {
        if (char === '"' && input[i + 1] === '"') { field += '"'; i += 1; }
        else if (char === '"') quoted = false;
        else field += char;
      } else if (char === '"') quoted = true;
      else if (char === ',') { row.push(field); field = ''; }
      else if (char === '\n') { row.push(field); rows.push(row); row = []; field = ''; }
      else if (char !== '\r') field += char;
    }
    if (field || row.length) { row.push(field); rows.push(row); }

    const [header, ...body] = rows.filter((r) => r.some((cell) => cell.trim() !== ''));
    if (!header) return [];
    const keys = header.map((h) => h.trim());
    return body.map((r) => Object.fromEntries(keys.map((k, i) => [k, (r[i] || '').trim()])));
  }

  /* ------------------------------ accept --------------------------- */

  /**
   * Normalise either payload shape: the bundled files wrap their data
   * ({ generatedAt, symbols }) while the caches store bare values.
   */
  function unwrap(payload, key) {
    if (Array.isArray(payload)) return payload;
    if (payload && payload[key] !== undefined) return payload[key];
    return null;
  }

  function acceptNse(symbolsPayload, basketsPayload) {
    const items = unwrap(symbolsPayload, 'symbols') || [];
    const baskets = unwrap(basketsPayload, 'baskets') || {};
    if (!items.length) return false;

    state.items = items.filter((item) => item && item.s);
    state.index = new Map(state.items.map((item) => [String(item.s).toUpperCase(), item]));
    state.baskets = (baskets && typeof baskets === 'object' && !Array.isArray(baskets)) ? baskets : {};
    state.updatedAt = (symbolsPayload && symbolsPayload.generatedAt)
      ? Date.parse(symbolsPayload.generatedAt) || 0 : 0;
    state.localised.clear();
    state.ready = state.items.length > 0;
    return state.ready;
  }

  /**
   * Accept the BSE-only payload. Called with `undefined` when the bundled
   * file is missing or an older cache has not stored BSE yet — an empty
   * list is fine, the NSE universe still works.
   */
  function acceptBse(payload) {
    const items = unwrap(payload, 'symbols') || [];
    state.bseItems = items.filter((item) => item && item.s);
    state.bseIndex = new Map(state.bseItems.map((item) => [String(item.s).toUpperCase(), item]));
    state.bseUpdatedAt = (payload && payload.generatedAt)
      ? Date.parse(payload.generatedAt) || 0 : 0;
    state.localised.clear();
  }

  /* ------------------------------- loading ------------------------- */

  async function loadBundled() {
    const [symbols, baskets, bse] = await Promise.all([
      fetch('data/nse-symbols.json', { cache: 'no-store' }).then((r) => r.json()),
      fetch('data/baskets.json', { cache: 'no-store' }).then((r) => r.json()).catch(() => null),
      fetch('data/bse-symbols.json', { cache: 'no-store' }).then((r) => r.json()).catch(() => null)
    ]);
    return { symbols, baskets, bse };
  }

  async function load() {
    if (state.ready) return state;
    if (state.loading) return state.loading;

    state.loading = (async () => {
      const cached = read(CACHE_KEY);
      if (cached && cached.savedAt && Date.now() - cached.savedAt < CACHE_MAX_AGE
        && acceptNse({ symbols: cached.items, generatedAt: cached.generatedAt }, { baskets: cached.baskets })) {
        state.refreshedAt = cached.savedAt;
        acceptBse({ symbols: cached.bseItems, generatedAt: cached.bseGeneratedAt });
        return state;
      }

      try {
        const { symbols, baskets, bse } = await loadBundled();
        acceptNse(symbols, baskets);
        state.refreshedAt = state.updatedAt;
        acceptBse(bse);
        write(CACHE_KEY, {
          savedAt: Date.now(),
          generatedAt: symbols.generatedAt || null,
          items: state.items,
          baskets: state.baskets,
          bseItems: state.bseItems,
          bseGeneratedAt: bse ? bse.generatedAt : null
        });
      } catch (err) {
        if (cached) {
          acceptNse({ symbols: cached.items, generatedAt: cached.generatedAt }, { baskets: cached.baskets });
          acceptBse({ symbols: cached.bseItems, generatedAt: cached.bseGeneratedAt });
        }
      }
      return state;
    })();

    return state.loading;
  }

  /* --------------------------- daily refresh ----------------------- */

  /** Fetch text through the configured proxies (no API key needed). */
  async function fetchText(url) {
    const attempts = [url, ...CONFIG.proxies.map((build) => build(url))];
    let lastError;
    for (const attempt of attempts) {
      try {
        const response = await fetch(attempt, { cache: 'no-store' });
        if (!response.ok) throw new Error(`HTTP ${response.status}`);
        return await response.text();
      } catch (err) { lastError = err; }
    }
    throw lastError || new Error('unreachable');
  }

  /** Pull the current symbol list and baskets straight from NSE. */
  async function refreshFromNse() {
    const equityCsv = await fetchText(EQUITY_URL);
    const equities = parseCsv(equityCsv).filter((row) => row.SYMBOL && row.SERIES === 'EQ');
    if (equities.length < 100) throw new Error('unexpected equity list');

    const industries = {};
    const baskets = {};

    for (const key of BASKET_FILES) {
      const csv = await fetchText(`https://nsearchives.nseindia.com/content/indices/ind_${key}list.csv`);
      const rows = parseCsv(csv);
      baskets[key] = rows.map((row) => row.Symbol).filter(Boolean);
      rows.forEach((row) => {
        if (row.Symbol && row.Industry && !industries[row.Symbol]) industries[row.Symbol] = row.Industry;
      });
    }

    const items = equities.map((row) => ({
      s: row.SYMBOL,
      n: (row['NAME OF COMPANY'] || '').replace(/,\s*$/, ''),
      ...(industries[row.SYMBOL] ? { i: industries[row.SYMBOL] } : {}),
      ...(row['ISIN NUMBER'] ? { isin: row['ISIN NUMBER'] } : {})
    }));

    acceptNse({ symbols: items, generatedAt: new Date().toISOString() }, { baskets });
    state.refreshedAt = Date.now();
    write(REFRESH_KEY, state.refreshedAt);
    write(CACHE_KEY, {
      savedAt: Date.now(),
      generatedAt: new Date().toISOString(),
      items: state.items,
      baskets: state.baskets,
      bseItems: state.bseItems,
      bseGeneratedAt: state.bseUpdatedAt ? new Date(state.bseUpdatedAt).toISOString() : null
    });
    return state.items.length;
  }

  /** Refresh at most once a day; never blocks the first render. */
  async function refreshIfStale() {
    const last = read(REFRESH_KEY) || 0;
    if (Date.now() - last < REFRESH_EVERY) return { refreshed: false, reason: 'fresh' };
    state.refreshedAt = last;
    try {
      const count = await refreshFromNse();
      return { refreshed: true, count };
    } catch (err) {
      write(REFRESH_KEY, Date.now()); // don't hammer a blocked network
      return { refreshed: false, reason: err.message };
    }
  }

  /* ----------------------------- BSE master ------------------------ */

  /** Walk back over weekends/holidays until a bhavcopy is available. */
  async function fetchBseMaster(maxDaysBack = 8) {
    let lastError;
    for (let back = 1; back <= maxDaysBack; back += 1) {
      const url = BSE_URL(new Date(Date.now() - back * 24 * 60 * 60 * 1000));
      try {
        return { csv: await fetchText(url), url };
      } catch (err) { lastError = err; }
    }
    throw lastError || new Error('no recent BSE bhavcopy');
  }

  /**
   * Re-download the BSE equity master on demand (the manual list refresh).
   * Scrips already covered by NSE — matched by ISIN first, then ticker —
   * are dropped so the two exchanges never duplicate a company.
   */
  async function refreshBse() {
    const { csv } = await fetchBseMaster();
    const rows = parseCsv(csv);
    const nseTickers = new Set(state.items.map((entry) => String(entry.s).toUpperCase()));
    const nseIsins = new Set(state.items.map((entry) => String(entry.isin || '').toUpperCase()).filter(Boolean));

    const seen = new Set();
    const items = [];
    rows.forEach((row) => {
      const ticker = (row.TckrSymb || '').trim();
      const isin = (row.ISIN || '').trim().toUpperCase();
      const name = (row.FinInstrmNm || '').trim();
      if (!ticker || !name) return;
      if ((row.FinInstrmTp || '').trim() !== 'STK') return;
      if (isin && nseIsins.has(isin)) return;
      if (nseTickers.has(ticker.toUpperCase())) return;
      if (seen.has(ticker.toUpperCase())) return;
      seen.add(ticker.toUpperCase());
      items.push({ s: ticker, n: name, ...(isin ? { isin } : {}) });
    });

    if (items.length < 100) throw new Error('unexpected BSE list');
    acceptBse({ symbols: items, generatedAt: new Date().toISOString() });
    write(CACHE_KEY, { ...(read(CACHE_KEY) || {}), savedAt: Date.now(), bseItems: state.bseItems, bseGeneratedAt: new Date().toISOString() });
    return items.length;
  }

  /* ------------------------------ lookup --------------------------- */

  /** Yahoo ticker for a bare code: `.NS` for NSE listings, `.BO` for BSE-only. */
  function toYahoo(symbol) {
    if (!symbol) return '';
    const raw = String(symbol);
    if (raw.startsWith('^') || raw.includes('.')) return raw;
    if (state.index.has(raw.toUpperCase())) return `${raw}.NS`;
    if (state.bseIndex.has(raw.toUpperCase())) return `${raw}.BO`;
    return `${raw}.NS`;
  }

  function fromYahoo(ticker) {
    return String(ticker || '').replace(/\.(NS|BO)$/i, '');
  }

  /** Universe entry for a bare code or a full `SYM.NS` / `SYM.BO` ticker. */
  function item(symbol) {
    const raw = String(symbol || '');
    if (!raw) return null;
    const key = fromYahoo(raw).toUpperCase();
    // An explicit .BO asks for the BSE record; otherwise NSE wins.
    if (/\.BO$/i.test(raw) && state.bseIndex.has(key)) return state.bseIndex.get(key);
    return state.index.get(key) || state.bseIndex.get(key) || null;
  }

  function officialName(symbol) {
    const found = item(symbol);
    return found ? found.n : '';
  }

  function sectorKey(symbol) {
    if (String(symbol).startsWith('^')) return 'index';
    const found = item(symbol);
    if (!found || !found.i) return 'other';
    return INDUSTRY_KEYS[found.i] || 'other';
  }

  /** Localised names for every symbol, built once per language. */
  function localisedIndex(lang) {
    if (state.localised.has(lang)) return state.localised.get(lang);
    const map = new Map();
    state.items.forEach((entry) => {
      map.set(entry.s, Localize.short(`${entry.s}.NS`, lang, entry.n));
    });
    state.bseItems.forEach((entry) => {
      if (!map.has(entry.s)) map.set(entry.s, Localize.short(`${entry.s}.BO`, lang, entry.n));
    });
    state.localised.set(lang, map);
    return map;
  }

  /** Localised display name for any symbol, indices included. */
  function name(symbol, lang) {
    const ticker = String(symbol).startsWith('^') ? symbol : toYahoo(symbol);
    const curated = Glossary.name(ticker, lang);
    if (curated) return curated;
    const found = item(symbol);
    if (!found) return symbol;
    return localisedIndex(lang).get(found.s) || found.n || fromYahoo(symbol);
  }

  /**
   * Languages whose script the query is written in, so a user can type
   * "ಇನ್ಫೋಸಿಸ್" or "இன்ஃபோசிஸ்" even while the UI is in another language.
   * Devanagari and Bengali are shared by two languages each.
   */
  const SCRIPT_HINTS = [
    { test: /[\u0900-\u097F]/, langs: ['hi', 'mr', 'kok', 'mai', 'doi', 'brx', 'sa'] },
    { test: /[\u0980-\u09FF]/, langs: ['bn', 'as', 'mni'] },
    { test: /[\u0A00-\u0A7F]/, langs: ['pa'] },
    { test: /[\u0A80-\u0AFF]/, langs: ['gu'] },
    { test: /[\u0B00-\u0B7F]/, langs: ['or'] },
    { test: /[\u0B80-\u0BFF]/, langs: ['ta'] },
    { test: /[\u0C00-\u0C7F]/, langs: ['te'] },
    { test: /[\u0C80-\u0CFF]/, langs: ['kn'] },
    { test: /[\u0D00-\u0D7F]/, langs: ['ml'] },
    { test: /[\u0600-\u06FF]/, langs: ['ur', 'sd', 'ks'] }
  ];

  function scriptsOf(query) {
    const langs = [];
    SCRIPT_HINTS.forEach((hint) => {
      if (hint.test.test(query)) langs.push(...hint.langs);
    });
    return langs;
  }

  /** Search the universe in any language (symbol, official or local name). */
  function search(query, lang, limit = 40) {
    const needle = String(query || '').trim();
    if (!needle) return [];
    const lower = needle.toLowerCase();

    // Current language first, then any other script the query is written in.
    const languages = Array.from(new Set([lang, ...scriptsOf(needle)].filter(Boolean)));
    const indexes = languages.map((code) => localisedIndex(code));
    const hits = [];

    for (const entry of state.items.concat(state.bseItems)) {
      const symbol = entry.s.toLowerCase();
      const official = (entry.n || '').toLowerCase();
      const locals = indexes.map((index) => (index.get(entry.s) || '').toLowerCase());

      let score = -1;
      if (symbol === lower) score = 0;
      else if (official.startsWith(lower) || locals.some((name) => name.startsWith(lower))) score = 1;
      else if (symbol.startsWith(lower)) score = 2;
      else if (official.includes(lower) || locals.some((name) => name.includes(lower))) score = 3;

      if (score >= 0) hits.push({ entry, score });
      if (hits.length > 600) break;
    }

    hits.sort((a, b) => (a.score - b.score) || a.entry.s.localeCompare(b.entry.s));
    const primary = localisedIndex(lang);
    return hits.slice(0, limit).map(({ entry }) => ({
      symbol: toYahoo(entry.s),
      bare: entry.s,
      official: entry.n,
      name: primary.get(entry.s) || entry.n,
      sector: INDUSTRY_KEYS[entry.i] || 'other'
    }));
  }

  /** Yahoo tickers for a basket key. */
  function basketSymbols(key) {
    const list = state.baskets[key];
    return Array.isArray(list) ? list.map(toYahoo) : [];
  }

  function basketKeys() {
    return Object.keys(state.baskets);
  }

  return {
    load,
    refreshIfStale,
    refreshFromNse,
    refreshBse,
    ready: () => state.ready,
    count: () => state.items.length,
    bseCount: () => state.bseItems.length,
    totalCount: () => state.items.length + state.bseItems.length,
    updatedAt: () => state.updatedAt,
    bseUpdatedAt: () => state.bseUpdatedAt,
    refreshedAt: () => state.refreshedAt,
    search,
    name,
    officialName,
    sectorKey,
    toYahoo,
    fromYahoo,
    item,
    basketSymbols,
    basketKeys,
    parseCsv,
    industryKeys: INDUSTRY_KEYS
  };
})();
